5	namespace AtrioTeam\DigitalHub\Pim\Filament\Schemas;
6	
7	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
8	use AtrioTeam\DigitalHub\Pim\Concerns\HasTechnicalAttributes;
9	use AtrioTeam\DigitalHub\Pim\Enum\Type;
10	use AtrioTeam\DigitalHub\Pim\TypeBuilder;
11	use Filament\Forms\Components\DatePicker;
12	use Filament\Forms\Components\Select;
13	use Filament\Forms\Components\Textarea;
14	use Filament\Forms\Components\TextInput;
15	use Filament\Forms\Components\Toggle;
16	use Filament\Schemas\Components\Component;
17	use Filament\Schemas\Components\Group;
18	use Filament\Schemas\Components\Section;
19	use Filament\Schemas\Components\Tabs;
20	use Filament\Schemas\Components\Tabs\Tab;
21	use Filament\Schemas\Components\Utilities\Get;
22	use Filament\Schemas\Schema;
23	use Illuminate\Database\Eloquent\Model;
24	
25	/**
26	 * Generatore Filament form da uno schema di attributi PIM.
27	 *
28	 * Uso tipico in una Resource:
29	 *   return $schema->components([
30	 *       TextInput::make('name'),
31	 *       AttributesEditorSection::for($schema),
32	 *   ]);
33	 *
34	 * Genera una Section "Dati tecnici" contenente una Tabs con un tab per ogni
35	 * gruppo dichiarato dallo schema; ogni tab contiene gli input giusti per
36	 * ciascun attributo (text/numeric/select/toggle/date) con label, required,
37	 * min/max, unit risolti dallo schema stesso.
38	 */
39	class AttributesEditorSection
40	{
41	    /**
42	     * Costruisce la section dei dati tecnici dal Filament Schema del form.
43	     *
44	     */
45	    public static function for(Schema $schema): Section
46	    {
47	        $instance = self::resolveInstance($schema);
48	
49	        /** @var AttributeSchema|null $attributeSchema */
50	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait, asserted in resolveInstance)
51	        $attributeSchema = $instance->attributeSchema();
52	
53	        return self::buildSection($instance, $attributeSchema);
54	    }
55	
56	    /**
57	     * Variante reattiva: avvolge la section in un container che si rigenera quando
58	     * cambia lo stato del form. Lo schema attributi da usare viene risolto a ogni
59	     * render dalla closure $schemaResolver, che riceve il Get del form.
60	     *
61	     * Perché serve: for() risolve lo schema una volta sola alla prima render. Su
62	     * un modello che risolve dinamicamente lo schema (es. Product → ProductType),
63	     * cambiare la tipologia nel form non aggiornerebbe i campi. Il container Group
64	     * con schema() a closure ri-esegue il resolver a ogni cambio reattivo.
65	     *
66	     * Il core resta agnostico su come si risolve lo schema: è il template a
67	     * fornire $schemaResolver (es. leggendo product_type_id da $get e mappandolo
68	     * sulla AttributeSchema della tipologia).
69	     *
70	     * @param \Closure(Get): ?AttributeSchema $schemaResolver
71	     */
72	    public static function reactive(Schema $schema, \Closure $schemaResolver): Group
73	    {
74	        $instance = self::resolveInstance($schema);
75	
76	        return Group::make()->schema(function (Get $get) use ($instance, $schemaResolver): array {
77	            return [self::buildSection($instance, $schemaResolver($get))];
78	        });
79	    }
80	
81	    /**
82	     * Risolve l'istanza del modello dal Filament Schema e ne verifica il trait.
83	     *
84	     * In update abbiamo l'istanza del record ($schema->getRecord()); in create
85	     * solo la class-string del modello ($schema->getModel()), da cui istanziamo.
86	     * La risoluzione dello schema attributi può dipendere dai dati del record
87	     * (es. Product risolve dallo schema della ProductType associata): una nuova
88	     * istanza vuota non li risolverebbe correttamente.
89	     */
90	    private static function resolveInstance(Schema $schema): Model
91	    {
92	        $recordOrClassName = $schema->getRecord() ?? $schema->getModel();
93	
94	        // if a concrete istance is not passed, create one.
95	        /** @var Model $instance */
96	        $instance = is_string($recordOrClassName) ? new $recordOrClassName() : $recordOrClassName;
97	
98	        // model must use HasTechnicalAttributes!
99	        if (! in_array(HasTechnicalAttributes::class, class_uses_recursive($instance), true)) {
100	            throw new \InvalidArgumentException(
101	                'Model [' . get_class($instance) . '] must use the HasTechnicalAttributes trait.',
102	            );
103	        }
104	
105	        return $instance;
106	    }
107	
108	    /**
109	     * Costruisce la Section "Dati tecnici" (con dentro la Tabs dei gruppi) da uno
110	     * schema esplicito. Lo schema è passato esplicitamente (non riletto da
111	     * $instance) così la variante reattiva può fornire uno schema diverso da
112	     * quello attualmente risolto sul record. Se lo schema è null (nessun
113	     * attributo), l'intera Section viene nascosta.
114	     *
115	     * @param Model $instance model using the HasTechnicalAttributes trait
116	     */
117	    private static function buildSection(Model $instance, ?AttributeSchema $attributeSchema): Section
118	    {
119	        /** @var string $column */
120	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
121	        $column = $instance->attributesColumn();
122	
123	        // lopp thorugh schema groups and attributes to build tabs and fields
124	        $tabs = [];
125	        $totalFieldsCount = 0;
126	        if ($attributeSchema !== null) {
127	            // regole di validazione per ogni attributo (incl. unique sul path JSON,
128	            // con ignore del record in update): risolte dal modello concreto.
129	            $validationRules = $attributeSchema->validationRules($instance);
130	
131	            foreach ($attributeSchema->groups() as $groupKey => $attrKeys) {
132	                $fields = [];
133	                foreach ($attrKeys as $key) {
134	                    $type = $attributeSchema->getType($key);
135	                    if ($type !== null) {
136	                        $fields[] = self::buildField($column, $key, $type, $instance, $validationRules[$key] ?? []);
137	                        $totalFieldsCount++;
138	                    }
139	                }
140	                /** @var string $groupLabel */
141	                // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
142	                $groupLabel = $instance->attrGroupLabel((string) $groupKey);
143	                $tabs[] = Tab::make($groupLabel)->schema($fields);
144	            }
145	        }
146	
147	
148	        $section = Section::make(__('digital-hub::fields.technical_data'))
149	            ->schema([Tabs::make()->tabs($tabs)]);
150	
151	        if ($totalFieldsCount === 0) {
152	            $section->hidden();
153	        }
154	
155	        return $section;
156	    }
157	
158	    /**
159	     * Model è atteso usare il trait HasTechnicalAttributes (controllato in for()).
160	     *
161	     * @param Model $instance model using the HasTechnicalAttributes trait
162	     * @param list<mixed> $validationRules regole Laravel per questo attributo (da AttributeSchema::validationRules)
163	     */
164	    private static function buildField(string $column, string $key, TypeBuilder $type, Model $instance, array $validationRules): Component
165	    {
166	        $name = "{$column}.{$key}";
167	        /** @var string $label */
168	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
169	        $label = $instance->attrLabel($key);
170	
171	        $field = match ($type->kind()) {
172	            Type::String => TextInput::make($name),
173	            Type::Text => Textarea::make($name)->rows(4),
174	            Type::Int => TextInput::make($name)->numeric()->integer(),
175	            Type::Decimal => TextInput::make($name)->numeric(),
176	            Type::Bool => Toggle::make($name),
177	            Type::Date => DatePicker::make($name),
178	            Type::Enum => Select::make($name)->options(
179	                array_combine(
180	                    $type->getOptions(),
181	                    array_map(
182	                        static function (string $opt) use ($instance, $key): string {
183	                            /** @var string $label */
184	                            // @phpstan-ignore method.notFound (HasTechnicalAttributes trait, returns string)
185	                            $label = $instance->attrOption($key, $opt);
186	
187	                            return $label;
188	                        },
189	                        $type->getOptions(),
190	                    ),
191	                ),
192	            ),
193	        };
194	
195	        $field->label($label);
196	
197	        if ($type->isRequired()) {
198	            $field->required();
199	        }
200	
201	        if ($type->getMin() !== null && method_exists($field, 'minValue')) {
202	            $field->minValue($type->getMin());
203	        }
204	
205	        if ($type->getMax() !== null && method_exists($field, 'maxValue')) {
206	            $field->maxValue($type->getMax());
207	        }
208	
209	        if ($type->getUnit() !== null && method_exists($field, 'suffix')) {
210	            $field->suffix($type->getUnit());
211	        }
212	
213	        // Regole non già mappate sui metodi nativi del field (required/min/max sopra):
214	        // in particolare unique, che opera sul path JSON e va imposta come regola Laravel.
215	        // Le stringhe scalari di base sono già coperte dai metodi nativi: si escludono per
216	        // non duplicarle.
217	        $extraRules = array_values(array_filter(
218	            $validationRules,
219	            static fn (mixed $rule): bool => ! is_string($rule)
220	                || ! preg_match('/^(required|nullable|string|integer|numeric|boolean|date|min:|max:|regex:)/', $rule),
221	        ));
222	
223	        if ($extraRules !== []) {
224	            $field->rules($extraRules);
225	        }
226	
227	        // Attributi translatable (solo String/Text): il valore è salvato come map
228	        // {locale: value} nello stesso JSON. Il campo viene avvolto in una
229	        // TranslationSection che lo clona per ogni locale gestita, spostando lo
230	        // statePath da {column}.{key} a {column}.{key}.{locale}. Stesso pattern del
231	        // `name` (NameAndId). Le regole native già applicate sopra (required/min/max)
232	        // vengono clonate su ogni tab, quindi valgono per-locale.
233	        if ($type->isTranslatable() && in_array($type->kind(), [Type::String, Type::Text], true)) {
234	            /** @var array<string, string> $locales */
235	            $locales = (array) config('digital-hub.locales');
236	
237	            return TranslationSection::make()
238	                ->locales($locales)
239	                ->schema([$field]);
240	        }
241	
242	        return $field;
243	    }
244	}
