5	namespace AtrioTeam\DigitalHub\Pim\Concerns;
6	
7	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
8	use Illuminate\Database\Eloquent\Builder;
9	
10	/**
11	 * Trait universale per modelli con attributi PIM su colonna JSON.
12	 *
13	 * Configurazione lato modello (entrambi opzionali):
14	 *   protected static string $attributesColumn = 'properties';     // default 'properties'
15	 *   protected static ?string $attributeSchemaClass = ProductAttributes::class;
16	 *
17	 * Nota sul nome della colonna: il default è 'properties', non 'attributes',
18	 * di proposito. Una colonna chiamata 'attributes' collide con la proprietà
19	 * dichiarata Eloquent Model::$attributes: l'accesso dinamico bypasserebbe il
20	 * cast e i metodi del trait leggerebbero l'intero array di attributi del
21	 * modello invece del JSON. Evitare di reintrodurre quel nome.
22	 *
23	 * Per risoluzione dinamica dello schema (es. in base a categoria) si può
24	 * sovrascrivere resolveAttributeSchemaClass() nel modello.
25	 *
26	 * Nota: il trait NON dichiara queste static properties — i modelli le
27	 * dichiarano direttamente. Questo evita il PHP property compatibility check
28	 * tra trait e classe usante.
29	 *
30	 * @mixin \Illuminate\Database\Eloquent\Model
31	 */
32	trait HasTechnicalAttributes
33	{
34	    public function initializeHasTechnicalAttributes(): void
35	    {
36	        $this->mergeCasts([$this->attributesColumn() => 'array']);
37	    }
38	
39	    public function resolveAttributeSchemaClass(): ?string
40	    {
41	        return property_exists(static::class, 'attributeSchemaClass')
42	            ? static::$attributeSchemaClass
43	            : null;
44	    }
45	
46	    public function attributeSchema(): ?AttributeSchema
47	    {
48	        $class = $this->resolveAttributeSchemaClass();
49	        if ($class === null) {
50	            return null;
51	        }
52	
53	        /** @var AttributeSchema $instance */
54	        $instance = new $class();
55	
56	        return $instance;
57	    }
58	
59	    public function attributesColumn(): string
60	    {
61	        if (! property_exists(static::class, 'attributesColumn')) {
62	            return 'properties';
63	        }
64	
65	        $column = static::$attributesColumn;
66	
67	        return is_string($column) ? $column : 'properties';
68	    }
69	
70	    /**
71	     * Valore corrente della colonna attributi come array.
72	     *
73	     * Passa esplicitamente da getAttribute() (sistema cast di Eloquent) invece
74	     * dell'accesso dinamico $this->{column}: quest'ultimo è ambiguo se il nome
75	     * della colonna coincide con una proprietà dichiarata del Model (es.
76	     * 'attributes' → Model::$attributes), nel qual caso bypasserebbe il cast.
77	     * Il default 'properties' evita la collisione, ma il modello può scegliere
78	     * qualunque nome: getAttribute()/setAttribute() restano corretti comunque.
79	     *
80	     * @return array<string, mixed>
